.period-select, .select-button { padding: 9px 11px; border: 1px solid var(--line); border-radius: 9px; outline: none; background: var(--panel); color: var(--muted); font-size: 10px; }.settings-layout { display: grid; grid-template-columns: 190px minmax(0, 1fr); gap: 13px; }.settings-nav { align-self: start; padding: 9px; }.settings-nav button { width: 100%; padding: 11px; border-radius: 9px; background: transparent; color: var(--muted); font-size: 10px; text-align: right; }.settings-nav button.active { background: var(--accent-soft); color: var(--accent); font-weight: 800; }.settings-content { padding: 21px; }.settings-section + .settings-section { padding-top: 16px; margin-top: 18px; border-top: 1px solid var(--line); }.settings-content .section-title { margin: 0 0 12px; }.setting-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 13px 0; border-bottom: 1px solid var(--line); }.setting-row:last-child { border-bottom: 0; }.setting-row strong, .setting-row small { display: block; }.setting-row strong { font-size: 11px; }.setting-row small { margin-top: 5px; color: var(--muted); font-size: 9px; }.toggle { width: 37px; height: 21px; padding: 3px; border-radius: 20px; background: var(--line); text-align: left; }.toggle i { display: block; width: 15px; height: 15px; border-radius: 50%; background: white; transition: transform .2s; }.toggle.on { background: var(--accent); }.toggle.on i { transform: translateX(-16px); }.color-picker { display: flex; gap: 7px; }.color-picker i { width: 18px; height: 18px; border-radius: 50%; background: var(--accent); }.color-picker i:nth-child(2) { background: var(--violet); }.color-picker i:nth-child(3) { background: #5cb5ff; }.color-picker i:nth-child(4) { background: #ff9d65; }.save-settings { width: 100%; padding: 11px; margin-top: 18px; border-radius: 9px; background: var(--accent); color: #052117; font-size: 10px; font-weight: 900; }

