/* ── SenPai Ink · Elon Musk Edition (default theme) ──
   True-black Tesla surface + high-contrast ink-white type + a single
   crimson "hanko stamp" accent, with the 10 living DNA colors doing
   the rest of the color work inside the brain/HUD. Kept restrained on
   purpose — 2026 dark-mode best practice is subtle depth, not neon
   soup. */
:root {
    --bg-canvas: #050608;
    --bg-panel: #0a0c10;
    --bg-raised: #12151b;
    --bg-input: #07080a;
    --bg-hover: #161a21;
    --border: #1e2229;
    --border-strong: #343a44;
    --border-active: #00d4ff;
    --text-primary: #f3f3f1;
    --text-secondary: #9a9da3;
    --text-dim: #52565d;
    --accent-blue: #00d4ff;
    --accent-violet: #b565ff;
    --accent-mint: #3ddc84;
    --accent-amber: #ffb347;
    --accent-red: #ff3b4e;
    --ink-red: #ff2d3d;
    --shadow-glow: rgba(0, 212, 255, 0.18);
    --mint-glow: rgba(61, 220, 132, 0.15);
    --violet-glow: rgba(181, 101, 255, 0.18);
    --font-mono: 'JetBrains Mono', 'Fira Code', monospace;
    --font-sans: 'Inter', 'Segoe UI', sans-serif;
    --font-display: 'Orbitron', 'Inter', sans-serif;
    --radius: 8px;
    --transition: 0.16s cubic-bezier(0.3, 0, 0.5, 1);
    --scrollbar-thumb: #23272e;
    /* ── Agent Vibe (Amber-Orange) ── */
    --agent-amber: #ffb347;
    --agent-orange: #ff8c42;
    --agent-glow: rgba(255, 140, 66, 0.25);
    --agent-glass: rgba(20, 14, 8, 0.55);
}

/* Subtle ink-grain texture over the whole app — reads as paper/ink,
   not neon-glass. Pure CSS, no image assets. */
body::before {
    content: '';
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 2;
    opacity: 0.035;
    mix-blend-mode: overlay;
    background-image:
        radial-gradient(circle at 20% 30%, #fff 0.5px, transparent 0.5px),
        radial-gradient(circle at 60% 70%, #fff 0.5px, transparent 0.5px),
        radial-gradient(circle at 80% 20%, #fff 0.5px, transparent 0.5px);
    background-size: 3px 3px, 5px 5px, 4px 4px;
}

/* ── GitHub Light Theme ── */
[data-theme="github-light"] {
    --bg-canvas: #ffffff;
    --bg-panel: #f6f8fa;
    --bg-raised: #f3f4f6;
    --bg-input: #ffffff;
    --bg-hover: #eaeef2;
    --border: #d0d7de;
    --border-strong: #8b949e;
    --border-active: #0969da;
    --text-primary: #1f2937;
    --text-secondary: #57606a;
    --text-dim: #8b949e;
    --accent-blue: #0969da;
    --accent-violet: #8250df;
    --accent-mint: #1a7f37;
    --accent-amber: #9a6700;
    --accent-red: #cf222e;
    --shadow-glow: rgba(9, 105, 218, 0.12);
    --mint-glow: rgba(26, 127, 55, 0.12);
    --violet-glow: rgba(130, 80, 223, 0.12);
    --scrollbar-thumb: #d0d7de;
}

/* ── Dracula Theme ── */
[data-theme="dracula"] {
    --bg-canvas: #282a36;
    --bg-panel: #1e1f2b;
    --bg-raised: #2d2f3e;
    --bg-input: #1e1f2b;
    --bg-hover: #3a3c4d;
    --border: #44475a;
    --border-strong: #6272a4;
    --border-active: #bd93f9;
    --text-primary: #f8f8f2;
    --text-secondary: #bfbfbf;
    --text-dim: #6272a4;
    --accent-blue: #8be9fd;
    --accent-violet: #bd93f9;
    --accent-mint: #50fa7b;
    --accent-amber: #f1fa8c;
    --accent-red: #ff5555;
    --shadow-glow: rgba(189, 147, 249, 0.15);
    --mint-glow: rgba(80, 250, 123, 0.15);
    --violet-glow: rgba(189, 147, 249, 0.15);
    --scrollbar-thumb: #44475a;
}

/* ── Solarized Dark ── */
[data-theme="solarized-dark"] {
    --bg-canvas: #002b36;
    --bg-panel: #073642;
    --bg-raised: #0a4a5a;
    --bg-input: #002b36;
    --bg-hover: #0a4a5a;
    --border: #586e75;
    --border-strong: #839496;
    --border-active: #268bd2;
    --text-primary: #fdf6e3;
    --text-secondary: #93a1a1;
    --text-dim: #586e75;
    --accent-blue: #268bd2;
    --accent-violet: #6c71c4;
    --accent-mint: #2aa198;
    --accent-amber: #b58900;
    --accent-red: #dc322f;
    --shadow-glow: rgba(38, 139, 210, 0.15);
    --mint-glow: rgba(42, 161, 152, 0.15);
    --violet-glow: rgba(108, 113, 196, 0.15);
    --scrollbar-thumb: #586e75;
}

/* ── High Contrast ── */
[data-theme="high-contrast"] {
    --bg-canvas: #000000;
    --bg-panel: #0a0a0a;
    --bg-raised: #1a1a1a;
    --bg-input: #000000;
    --bg-hover: #222222;
    --border: #ffffff;
    --border-strong: #ffffff;
    --border-active: #ffffff;
    --text-primary: #ffffff;
    --text-secondary: #e0e0e0;
    --text-dim: #888888;
    --accent-blue: #ffffff;
    --accent-violet: #ffffff;
    --accent-mint: #ffffff;
    --accent-amber: #ffffff;
    --accent-red: #ffffff;
    --shadow-glow: rgba(255, 255, 255, 0.25);
    --mint-glow: rgba(255, 255, 255, 0.25);
    --violet-glow: rgba(255, 255, 255, 0.25);
    --scrollbar-thumb: #444444;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    background: var(--bg-canvas);
    font-family: var(--font-sans);
    color: var(--text-primary);
    overflow: hidden;
    height: 100vh;
    width: 100vw;
    user-select: none;
    -webkit-user-select: none;
    -webkit-tap-highlight-color: transparent;
    font-feature-settings: "tnum" 1;
    transition: background 0.3s ease, color 0.3s ease;
}

::-webkit-scrollbar {
    width: 5px;
    height: 5px;
}
::-webkit-scrollbar-track {
    background: transparent;
}
::-webkit-scrollbar-thumb {
    background: var(--scrollbar-thumb);
    border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
    background: var(--border-strong);
}

.hex-bg {
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 0;
    opacity: 0.04;
    background-image: linear-gradient(60deg, var(--accent-blue) 1px, transparent 1px),
        linear-gradient(-60deg, var(--accent-blue) 1px, transparent 1px),
        linear-gradient(0deg, var(--accent-blue) 1px, transparent 1px);
    background-size: 30px 52px, 30px 52px, 60px 30px;
    animation: hexDrift 60s linear infinite;
    transition: opacity 0.3s ease;
}
[data-theme="github-light"] .hex-bg {
    opacity: 0.02;
}
[data-theme="high-contrast"] .hex-bg {
    opacity: 0.06;
}

@keyframes hexDrift {
    0% {
        background-position: 0 0, 0 0, 0 0;
    }
    100% {
        background-position: 60px 104px, 60px 104px, 120px 60px;
    }
}

.app-container {
    position: relative;
    display: flex;
    width: 100%;
    height: 100%;
    z-index: 1;
}

.brain-section {
    flex: 0 0 56%;
    position: relative;
    height: 100%;
    cursor: grab;
    overflow: hidden;
    background: radial-gradient(ellipse at center, var(--bg-panel) 0%, var(--bg-canvas) 100%);
    transition: background 0.3s ease, flex 0.4s ease;
}
.brain-section:active {
    cursor: grabbing;
}
.brain-section canvas {
    display: block !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    width: 100% !important;
    height: 100% !important;
    z-index: 1;
}
.brain-section.zen-hidden {
    flex: 0 0 0 !important;
    display: none;
}

.hud-overlay {
    position: absolute;
    inset: 0;
    pointer-events: none;
    z-index: 5;
}

.corner-bracket {
    position: absolute;
    width: 28px;
    height: 28px;
    pointer-events: none;
}
.corner-bracket::before,
.corner-bracket::after {
    content: '';
    position: absolute;
    background: var(--accent-blue);
    box-shadow: 0 0 8px var(--shadow-glow);
    opacity: 0.5;
    transition: background 0.3s ease, box-shadow 0.3s ease;
}
.bracket-tl {
    top: 14px;
    left: 14px;
}
.bracket-tl::before {
    top: 0;
    left: 0;
    width: 100%;
    height: 1.5px;
}
.bracket-tl::after {
    top: 0;
    left: 0;
    width: 1.5px;
    height: 100%;
}
.bracket-tr {
    top: 14px;
    right: 14px;
}
.bracket-tr::before {
    top: 0;
    right: 0;
    width: 100%;
    height: 1.5px;
}
.bracket-tr::after {
    top: 0;
    right: 0;
    width: 1.5px;
    height: 100%;
}
.bracket-bl {
    bottom: 14px;
    left: 14px;
}
.bracket-bl::before {
    bottom: 0;
    left: 0;
    width: 100%;
    height: 1.5px;
}
.bracket-bl::after {
    bottom: 0;
    left: 0;
    width: 1.5px;
    height: 100%;
}
.bracket-br {
    bottom: 14px;
    right: 14px;
}
.bracket-br::before {
    bottom: 0;
    right: 0;
    width: 100%;
    height: 1.5px;
}
.bracket-br::after {
    bottom: 0;
    right: 0;
    width: 1.5px;
    height: 100%;
}

.scan-line {
    position: absolute;
    left: 0;
    width: 100%;
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--accent-blue), var(--accent-violet), var(--accent-blue), transparent);
    box-shadow: 0 0 24px var(--accent-blue), 0 0 70px var(--shadow-glow);
    animation: scanSweep 5s ease-in-out infinite;
    pointer-events: none;
    opacity: 0.4;
    transition: background 0.3s ease, box-shadow 0.3s ease;
}
@keyframes scanSweep {
    0%,
    100% {
        top: -5%;
        opacity: 0;
    }
    8% {
        opacity: 0.6;
    }
    50% {
        top: 105%;
        opacity: 0.4;
    }
    92% {
        opacity: 0;
    }
}

.arc-ring {
    position: absolute;
    border-radius: 50%;
    border: 1px solid transparent;
    pointer-events: none;
    transition: border-color 0.3s ease;
}
.arc-ring-1 {
    width: 320px;
    height: 320px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    border-top-color: rgba(88, 166, 255, 0.3);
    border-right-color: rgba(88, 166, 255, 0.06);
    animation: arcRotate 20s linear infinite;
}
.arc-ring-2 {
    width: 400px;
    height: 400px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    border-bottom-color: rgba(210, 168, 255, 0.24);
    border-left-color: rgba(210, 168, 255, 0.06);
    animation: arcRotate 28s linear infinite reverse;
}
.arc-ring-3 {
    width: 250px;
    height: 250px;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) rotate(30deg);
    border-top-color: rgba(63, 185, 80, 0.2);
    border-left-color: rgba(63, 185, 80, 0.04);
    animation: arcRotate 24s linear infinite;
}
@keyframes arcRotate {
    from {
        transform: translate(-50%, -50%) rotate(0deg);
    }
    to {
        transform: translate(-50%, -50%) rotate(360deg);
    }
}

.status-labels {
    position: absolute;
    bottom: 18px;
    left: 18px;
    display: flex;
    flex-direction: column;
    gap: 5px;
    pointer-events: none;
}
.status-label {
    font-family: var(--font-display);
    font-size: 8px;
    font-weight: 500;
    letter-spacing: 1.8px;
    color: var(--accent-blue);
    text-shadow: 0 0 14px var(--shadow-glow);
    opacity: 0.9;
    display: flex;
    align-items: center;
    gap: 8px;
    text-transform: uppercase;
    transition: color 0.3s ease, text-shadow 0.3s ease;
}
.status-dot {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: var(--accent-mint);
    box-shadow: 0 0 10px var(--accent-mint);
    animation: dotPulse 2s ease-in-out infinite;
    flex-shrink: 0;
    transition: background 0.3s ease, box-shadow 0.3s ease;
}
.status-dot.warning {
    background: var(--accent-red);
    box-shadow: 0 0 10px var(--accent-red);
    animation: dotPulseFast 0.7s ease-in-out infinite;
}
.status-dot.recording {
    background: #ff2222;
    box-shadow: 0 0 20px #ff0000, 0 0 40px rgba(255, 0, 0, 0.4);
    animation: dotPulseFast 0.4s ease-in-out infinite;
}
@keyframes dotPulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.2;
    }
}
@keyframes dotPulseFast {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.08;
    }
}

.data-readouts {
    position: absolute;
    top: 18px;
    right: 18px;
    display: flex;
    flex-direction: column;
    gap: 4px;
    pointer-events: none;
    text-align: right;
}
.data-readout {
    font-family: var(--font-mono);
    font-size: 8.5px;
    font-weight: 400;
    color: var(--text-secondary);
    letter-spacing: 0.5px;
    transition: color 0.3s ease;
}
.data-readout span {
    color: var(--accent-blue);
    font-weight: 600;
    text-shadow: 0 0 10px var(--shadow-glow);
    transition: color 0.3s ease, text-shadow 0.3s ease;
}
.data-readout span.mint {
    color: var(--accent-mint);
    text-shadow: 0 0 10px var(--mint-glow);
}
.data-readout span.violet {
    color: var(--accent-violet);
    text-shadow: 0 0 10px var(--violet-glow);
}

.dna-legend-toggle {
    position: absolute;
    bottom: 18px;
    right: 18px;
    z-index: 5;
    pointer-events: auto;
    cursor: pointer;
    font-family: var(--font-mono);
    font-size: 9px;
    font-weight: 600;
    letter-spacing: 0.6px;
    color: var(--text-secondary);
    background: rgba(13, 17, 23, 0.55);
    border: 1px solid var(--border);
    border-radius: 999px;
    padding: 6px 12px;
    backdrop-filter: blur(6px);
    transition: color var(--transition), border-color var(--transition), background var(--transition), transform var(--transition);
}
.dna-legend-toggle:hover {
    color: var(--text-primary);
    border-color: var(--border-active);
    background: rgba(13, 17, 23, 0.8);
    transform: translateY(-1px);
}
.dna-legend-toggle[aria-expanded="true"] {
    color: var(--bg-canvas);
    background: var(--accent-blue);
    border-color: var(--accent-blue);
}
.dna-legend-panel {
    position: absolute;
    bottom: 56px;
    right: 18px;
    z-index: 6;
    width: 210px;
    max-height: 0;
    overflow: hidden;
    opacity: 0;
    pointer-events: none;
    background: rgba(13, 17, 23, 0.82);
    border: 1px solid var(--border);
    border-radius: 10px;
    backdrop-filter: blur(10px);
    box-shadow: 0 8px 28px rgba(0,0,0,0.45);
    transition: max-height 0.28s cubic-bezier(0.3,0,0.2,1), opacity 0.2s ease, transform 0.28s cubic-bezier(0.3,0,0.2,1);
    transform: translateY(6px);
}
.dna-legend-panel.open {
    max-height: 320px;
    opacity: 1;
    pointer-events: auto;
    transform: translateY(0);
}
.dna-legend-title {
    font-family: var(--font-mono);
    font-size: 8px;
    letter-spacing: 1px;
    color: var(--text-dim);
    padding: 10px 12px 6px;
    border-bottom: 1px solid var(--border);
}
.dna-legend-list {
    display: flex;
    flex-direction: column;
    padding: 6px 4px;
    max-height: 260px;
    overflow-y: auto;
}
.dna-legend-item {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 5px 8px;
    border-radius: 6px;
    transition: background var(--transition);
}
.dna-legend-item:hover {
    background: var(--bg-hover);
}
.dna-legend-swatch {
    flex-shrink: 0;
    width: 12px;
    height: 12px;
    border-radius: 3px;
    box-shadow: 0 0 8px 0 var(--sw-glow, transparent);
}
.dna-legend-name {
    font-family: var(--font-sans);
    font-size: 11px;
    font-weight: 600;
    color: var(--text-primary);
    line-height: 1.1;
}
.dna-legend-shape {
    margin-left: auto;
    font-family: var(--font-mono);
    font-size: 8px;
    color: var(--text-dim);
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.chat-panel {
    flex: 0 0 44%;
    height: 100%;
    display: flex;
    flex-direction: column;
    background: var(--bg-panel);
    border-left: 1px solid var(--border);
    box-shadow: -6px 0 40px rgba(0, 0, 0, 0.6);
    z-index: 5;
    position: relative;
    transition: background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease, flex 0.4s ease;
}
.chat-panel.zen-expanded {
    flex: 1 1 100%;
    border-left: none;
}
.chat-panel::before {
    content: '';
    position: absolute;
    top: 0;
    left: -1px;
    width: 1px;
    height: 100%;
    background: linear-gradient(180deg, transparent 0%, var(--accent-blue) 30%, var(--accent-violet) 70%, transparent 100%);
    opacity: 0.2;
    animation: edgeGlow 4s ease-in-out infinite;
    pointer-events: none;
    z-index: 10;
    transition: background 0.3s ease;
}
.chat-panel::after {
    content: '';
    position: absolute;
    top: 0;
    left: -8px;
    width: 8px;
    height: 100%;
    background: linear-gradient(90deg, transparent, var(--shadow-glow));
    pointer-events: none;
    z-index: 9;
    animation: edgeGlow 4s ease-in-out infinite;
    transition: background 0.3s ease;
}
@keyframes edgeGlow {
    0%,
    100% {
        opacity: 0.1;
    }
    50% {
        opacity: 0.5;
    }
}

.chat-header {
    padding: 10px 14px;
    border-bottom: 1px solid var(--border);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 6px;
    flex-shrink: 0;
    flex-wrap: wrap;
    background: linear-gradient(180deg, rgba(13, 17, 23, 0.9) 0%, rgba(22, 27, 34, 0.7) 100%);
    transition: background 0.3s ease, border-color 0.3s ease;
}
[data-theme="github-light"] .chat-header {
    background: linear-gradient(180deg, rgba(246, 248, 250, 0.9) 0%, rgba(255, 255, 255, 0.7) 100%);
}

.chat-header-title {
    font-family: var(--font-display);
    font-size: 13px;
    font-weight: 700;
    letter-spacing: 2.5px;
    color: var(--accent-blue);
    text-shadow: 0 0 20px var(--shadow-glow), 0 0 40px rgba(88, 166, 255, 0.15);
    white-space: nowrap;
    display: flex;
    align-items: center;
    transition: color 0.3s ease, text-shadow 0.3s ease;
}
.chat-header-title .badge {
    font-family: var(--font-display);
    font-size: 7px;
    font-weight: 700;
    background: var(--ink-red, var(--accent-red));
    color: #0a0a0a;
    padding: 2px 8px;
    border-radius: 3px;
    margin-left: 8px;
    letter-spacing: 1px;
    text-shadow: none;
    transform: skewX(-8deg);
    box-shadow: 0 0 14px rgba(255, 45, 61, 0.45);
    transition: background 0.3s ease, color 0.3s ease;
}
.header-actions {
    display: flex;
    gap: 5px;
    align-items: center;
    flex-wrap: wrap;
}
/* Header buttons are clustered into semantic groups (modes / tools /
   system) instead of one undifferentiated row. A hairline separator
   sits between groups so the eye can parse them at a glance. */
.header-group {
    display: flex;
    gap: 5px;
    align-items: center;
    padding-inline-end: 8px;
    margin-inline-end: 3px;
    border-inline-end: 1px solid var(--border);
}
.header-group:last-child {
    border-inline-end: none;
    padding-inline-end: 0;
    margin-inline-end: 0;
}
.header-group.group-system {
    margin-inline-start: 2px;
}
/* Shared icon used inside hud-btn / icon-btn / tool-btn */
.btn-icon {
    width: 13px;
    height: 13px;
    flex-shrink: 0;
    fill: none;
    stroke: currentColor;
    stroke-width: 2;
    stroke-linecap: round;
    stroke-linejoin: round;
    pointer-events: none;
}
.icon-btn .btn-icon {
    width: 15px;
    height: 15px;
}
.hud-btn {
    font-family: var(--font-display);
    font-size: 7.5px;
    font-weight: 600;
    letter-spacing: 1px;
    padding: 5px 10px;
    background: transparent;
    border: 1px solid var(--border);
    color: var(--text-secondary);
    cursor: pointer;
    transition: all var(--transition);
    text-transform: uppercase;
    white-space: nowrap;
    border-radius: 4px;
    display: inline-flex;
    align-items: center;
    gap: 4px;
}
/* Icon-only variant for compact/secondary header buttons (search,
   history, TTS, export, DNA legend) — tooltip carries the label. */
.hud-btn.icon-only {
    padding: 6px;
    width: 26px;
    height: 26px;
    justify-content: center;
}
.hud-btn:hover {
    background: var(--bg-hover);
    border-color: var(--border-active);
    color: var(--text-primary);
    box-shadow: 0 0 12px var(--shadow-glow);
}
.hud-btn.active-btn {
    background: rgba(88, 166, 255, 0.1);
    border-color: var(--accent-blue);
    color: var(--accent-blue);
    box-shadow: 0 0 20px var(--shadow-glow);
}
.hud-btn.danger {
    border-color: rgba(248, 81, 73, 0.3);
    color: var(--accent-red);
}
.hud-btn.danger:hover {
    background: rgba(248, 81, 73, 0.1);
    border-color: var(--accent-red);
    box-shadow: 0 0 12px rgba(248, 81, 73, 0.2);
}

/* New header elements */
.model-switcher {
    font-family: var(--font-mono);
    font-size: 8px;
    background: var(--bg-input);
    border: 1px solid var(--border);
    color: var(--text-primary);
    padding: 2px 6px;
    border-radius: 4px;
    cursor: pointer;
    max-width: 120px;
    outline: none;
}
.model-switcher:focus {
    border-color: var(--accent-blue);
}

/* Tabs */
.tab-bar {
    display: flex;
    gap: 2px;
    padding: 4px 10px;
    border-bottom: 1px solid var(--border);
    background: rgba(13, 17, 23, 0.3);
    flex-shrink: 0;
    overflow-x: auto;
    flex-wrap: nowrap;
}
.tab-item {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 4px 10px;
    border: 1px solid transparent;
    border-radius: 4px;
    font-size: 9px;
    font-family: var(--font-mono);
    color: var(--text-secondary);
    cursor: pointer;
    white-space: nowrap;
    transition: all var(--transition);
}
.tab-item:hover {
    background: var(--bg-hover);
    color: var(--text-primary);
}
.tab-item.active {
    background: rgba(88, 166, 255, 0.1);
    border-color: var(--accent-blue);
    color: var(--accent-blue);
}
.tab-item .tab-close {
    background: none;
    border: none;
    color: var(--text-dim);
    cursor: pointer;
    font-size: 10px;
    padding: 0 2px;
}
.tab-item .tab-close:hover {
    color: var(--accent-red);
}
.tab-add-btn {
    background: none;
    border: 1px dashed var(--border);
    color: var(--text-secondary);
    cursor: pointer;
    font-size: 12px;
    padding: 0 8px;
    border-radius: 4px;
    transition: all var(--transition);
}
.tab-add-btn:hover {
    border-color: var(--accent-blue);
    color: var(--accent-blue);
}

.token-meter {
    padding: 7px 14px 8px;
    border-bottom: 1px solid var(--border);
    background: rgba(13, 17, 23, 0.5);
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    gap: 5px;
    transition: background 0.3s ease, border-color 0.3s ease;
}
[data-theme="github-light"] .token-meter {
    background: rgba(255, 255, 255, 0.3);
}

.token-meter-row {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    font-family: var(--font-mono);
    font-size: 8.5px;
    letter-spacing: 0.4px;
    color: var(--text-secondary);
    gap: 8px;
}
.token-meter-row .tm-label {
    font-family: var(--font-display);
    text-transform: uppercase;
    letter-spacing: 1.5px;
    color: var(--text-dim);
    flex-shrink: 0;
    font-size: 7.5px;
}
.token-meter-row .tm-stats {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    justify-content: flex-end;
}
.token-meter-row .tm-stats b {
    color: var(--text-primary);
    font-weight: 600;
    transition: color 0.3s ease;
}
.token-meter-row .tm-stats .used {
    color: var(--accent-amber);
}
.token-meter-row .tm-stats .cost {
    color: var(--accent-mint);
}
.tm-gauge {
    position: relative;
    height: 13px;
    width: 100%;
    background: var(--bg-input);
    border: 1px solid var(--border);
    border-radius: 3px;
    overflow: hidden;
    display: flex;
    gap: 1.5px;
    padding: 1.5px;
    transition: background 0.3s ease, border-color 0.3s ease;
}
.token-meter.collapsed .tm-gauge { display: none; }
.token-meter.collapsed #tmChevron { transform: rotate(-90deg); }
.tm-tick {
    flex: 1;
    background: var(--border);
    border-radius: 1px;
    transition: background 0.25s, box-shadow 0.25s;
}
.tm-tick.filled {
    background: var(--accent-mint);
    box-shadow: 0 0 6px var(--mint-glow);
}
.tm-tick.filled.warn {
    background: var(--accent-amber);
    box-shadow: 0 0 6px rgba(210, 153, 34, 0.3);
}
.tm-tick.filled.crit {
    background: var(--accent-red);
    box-shadow: 0 0 6px rgba(248, 81, 73, 0.35);
}
.tm-tick.pulse {
    animation: tmPulse 0.5s ease-out;
}
@keyframes tmPulse {
    0% {
        filter: brightness(2.5);
    }
    100% {
        filter: brightness(1);
    }
}

.messages-container {
    flex: 1;
    overflow-y: auto;
    padding: 14px 16px;
    display: flex;
    flex-direction: column;
    gap: 12px;
    scroll-behavior: smooth;
    background: linear-gradient(180deg, rgba(13, 17, 23, 0.4) 0%, rgba(22, 27, 34, 0.3) 100%);
    transition: background 0.3s ease;
}
[data-theme="github-light"] .messages-container {
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.4) 0%, rgba(246, 248, 250, 0.3) 100%);
}
[data-theme="dracula"] .messages-container {
    background: linear-gradient(180deg, rgba(30, 31, 43, 0.4) 0%, rgba(40, 42, 54, 0.3) 100%);
}

/* Pinned messages area */
.pinned-messages-area {
    display: none;
    padding: 8px 12px;
    border-bottom: 1px solid var(--border);
    background: rgba(255, 215, 0, 0.05);
    flex-shrink: 0;
    max-height: 120px;
    overflow-y: auto;
}
.pinned-messages-area.visible {
    display: block;
}
.pinned-messages-area .pinned-title {
    font-size: 8px;
    font-family: var(--font-display);
    color: var(--accent-amber);
    letter-spacing: 1px;
    margin-bottom: 4px;
}
.pinned-message-item {
    font-size: 10px;
    color: var(--text-secondary);
    padding: 2px 0;
    border-bottom: 1px solid var(--border);
    display: flex;
    justify-content: space-between;
}
.pinned-message-item .unpin-btn {
    background: none;
    border: none;
    color: var(--text-dim);
    cursor: pointer;
    font-size: 8px;
}
.pinned-message-item .unpin-btn:hover {
    color: var(--accent-red);
}

.message-wrapper {
    display: flex;
    flex-direction: column;
    gap: 4px;
    animation: msgIn 0.28s ease-out;
    position: relative;
}
.message-wrapper.user-wrapper {
    align-items: flex-end;
}
.message-wrapper.ai-wrapper {
    align-items: flex-start;
}
@keyframes msgIn {
    from {
        opacity: 0;
        transform: translateY(10px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.message {
    max-width: 92%;
    padding: 10px 14px;
    border-radius: var(--radius);
    font-size: 12.5px;
    line-height: 1.68;
    word-break: break-word;
    position: relative;
    font-family: var(--font-sans);
    transition: background 0.3s ease, border-color 0.3s ease, color 0.3s ease;
}
.message.user {
    background: rgba(88, 166, 255, 0.07);
    border: 1px solid rgba(88, 166, 255, 0.18);
    color: var(--text-primary);
    text-align: left;
    box-shadow: 0 2px 20px var(--shadow-glow);
}
.message.user.editable {
    cursor: text;
    outline: 2px solid var(--accent-blue);
}
.message.ai {
    background: rgba(210, 168, 255, 0.04);
    border: 1px solid rgba(210, 168, 255, 0.13);
    color: var(--text-primary);
    box-shadow: 0 2px 20px var(--violet-glow);
}
.message.ai pre {
    background: var(--bg-canvas);
    padding: 10px 12px;
    border-radius: 4px;
    overflow-x: auto;
    font-size: 10.5px;
    border: 1px solid var(--border);
    margin: 8px 0;
    font-family: var(--font-mono);
    transition: background 0.3s ease, border-color 0.3s ease;
    position: relative;
}
.message.ai pre .code-copy-btn {
    position: absolute;
    top: 6px;
    right: 6px;
    background: var(--bg-panel);
    border: 1px solid var(--border);
    color: var(--text-secondary);
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 7px;
    cursor: pointer;
    font-family: var(--font-display);
    opacity: 0;
    transition: opacity 0.2s;
}
.message.ai pre:hover .code-copy-btn {
    opacity: 1;
}
.message.ai pre .code-copy-btn:hover {
    background: var(--bg-hover);
    border-color: var(--border-active);
    color: var(--text-primary);
}
.message.ai pre .code-run-btn {
    position: absolute;
    top: 6px;
    right: 50px;
    background: rgba(63, 185, 80, 0.1);
    border: 1px solid var(--accent-mint);
    color: var(--accent-mint);
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 7px;
    cursor: pointer;
    font-family: var(--font-display);
    opacity: 0;
    transition: opacity 0.2s;
}
.message.ai pre:hover .code-run-btn {
    opacity: 1;
}
.message.ai pre .code-run-btn:hover {
    background: rgba(63, 185, 80, 0.2);
}
.message.ai code {
    font-family: var(--font-mono);
    font-size: 10.5px;
    background: rgba(0, 0, 0, 0.4);
    padding: 1px 5px;
    border-radius: 3px;
    border: 1px solid var(--border);
    transition: background 0.3s ease, border-color 0.3s ease;
}
.message.ai pre code {
    background: none;
    padding: 0;
    border: none;
}
.message.ai p {
    margin: 4px 0;
}
.message.ai ul,
.message.ai ol {
    padding-left: 20px;
    margin: 6px 0;
}
.message.ai h1,
.message.ai h2,
.message.ai h3 {
    font-family: var(--font-display);
    font-weight: 600;
    margin: 8px 0 4px;
    color: var(--accent-blue);
    letter-spacing: 1px;
    transition: color 0.3s ease;
}
.message.ai a {
    color: var(--accent-blue);
    text-decoration: none;
}
.message.ai a:hover {
    text-decoration: underline;
}
.message.ai blockquote {
    border-left: 3px solid var(--accent-violet);
    padding-left: 12px;
    margin: 6px 0;
    color: var(--text-secondary);
    font-style: italic;
    transition: border-color 0.3s ease, color 0.3s ease;
}

/* Code execution console output */
.code-output {
    background: var(--bg-canvas);
    border: 1px solid var(--border);
    border-radius: 4px;
    padding: 8px 12px;
    font-family: var(--font-mono);
    font-size: 10px;
    margin-top: 4px;
    color: var(--text-secondary);
    max-height: 150px;
    overflow-y: auto;
    white-space: pre-wrap;
}
.code-output.error {
    border-color: var(--accent-red);
    color: var(--accent-red);
}

.message-meta {
    font-family: var(--font-mono);
    font-size: 7.5px;
    color: var(--text-dim);
    letter-spacing: 0.4px;
    padding: 0 4px;
    display: flex;
    gap: 8px;
}
.message-meta .mm-tok {
    color: var(--accent-amber);
}
.message-meta .mm-cost {
    color: var(--accent-mint);
}
.message-meta .mm-lat {
    color: var(--accent-blue);
}

.message-actions {
    display: flex;
    gap: 4px;
    opacity: 0;
    transition: opacity 0.2s;
    padding: 2px 4px;
    align-self: flex-start;
    flex-wrap: wrap;
}
.message-wrapper:hover .message-actions {
    opacity: 1;
}
.msg-action-btn {
    background: transparent;
    border: 1px solid var(--border);
    color: var(--text-secondary);
    cursor: pointer;
    font-size: 7.5px;
    padding: 2px 8px;
    border-radius: 3px;
    font-family: var(--font-display);
    transition: all var(--transition);
    white-space: nowrap;
    display: inline-flex;
    align-items: center;
    gap: 3px;
    letter-spacing: 0.5px;
}
.msg-action-btn:hover {
    background: var(--bg-hover);
    border-color: var(--border-active);
    color: var(--text-primary);
}
.msg-action-btn.copied {
    background: rgba(63, 185, 80, 0.12);
    border-color: var(--accent-mint);
    color: var(--accent-mint);
}
.msg-action-btn.active-feedback {
    background: rgba(88, 166, 255, 0.1);
    border-color: var(--accent-blue);
    color: var(--accent-blue);
}

.image-preview-container {
    display: flex;
    flex-wrap: wrap;
    gap: 5px;
    margin-top: 6px;
    max-width: 100%;
}
.image-preview {
    position: relative;
    border: 1px solid var(--border);
    border-radius: 4px;
    overflow: hidden;
    max-width: 100px;
    max-height: 80px;
    flex-shrink: 0;
    background: var(--bg-canvas);
    transition: border-color 0.3s ease;
}
.image-preview img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}
.image-preview .remove-img {
    position: absolute;
    top: 2px;
    right: 2px;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: rgba(0, 0, 0, 0.8);
    border: 1px solid var(--accent-red);
    color: #fff;
    cursor: pointer;
    font-size: 9px;
    line-height: 16px;
    text-align: center;
    padding: 0;
    transition: all var(--transition);
}
.image-preview .remove-img:hover {
    background: var(--accent-red);
}

.typing-indicator {
    align-self: flex-start;
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 9px 14px;
    background: rgba(210, 168, 255, 0.04);
    border: 1px solid rgba(210, 168, 255, 0.12);
    border-radius: var(--radius);
    font-size: 9.5px;
    font-family: var(--font-display);
    color: var(--text-secondary);
    letter-spacing: 1.5px;
    animation: msgIn 0.28s ease-out;
}
.waveform-svg {
    width: 28px;
    height: 18px;
}
.waveform-svg .bar {
    animation: waveAnim 0.8s ease-in-out infinite;
    fill: var(--accent-blue);
    transition: fill 0.3s ease;
}
.waveform-svg .bar:nth-child(2) {
    animation-delay: 0.1s;
}
.waveform-svg .bar:nth-child(3) {
    animation-delay: 0.2s;
}
.waveform-svg .bar:nth-child(4) {
    animation-delay: 0.3s;
}
.waveform-svg .bar:nth-child(5) {
    animation-delay: 0.4s;
}
@keyframes waveAnim {
    0%,
    100% {
        height: 3px;
    }
    50% {
        height: 14px;
    }
}

.scroll-bottom-btn {
    position: absolute;
    bottom: 82px;
    right: 14px;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: var(--bg-panel);
    border: 1px solid var(--border);
    color: var(--text-secondary);
    cursor: pointer;
    display: none;
    align-items: center;
    justify-content: center;
    font-size: 13px;
    z-index: 20;
    transition: all var(--transition);
}
.scroll-bottom-btn:hover {
    background: var(--bg-hover);
    border-color: var(--border-active);
    color: var(--text-primary);
}
.scroll-bottom-btn.visible {
    display: flex;
}

.input-area {
    padding: 10px 14px;
    border-top: 1px solid var(--border);
    display: flex;
    gap: 6px;
    align-items: flex-end;
    flex-shrink: 0;
    background: linear-gradient(180deg, rgba(13, 17, 23, 0.8) 0%, rgba(13, 17, 23, 0.9) 100%);
    flex-wrap: wrap;
    transition: background 0.3s ease, border-color 0.3s ease;
}
[data-theme="github-light"] .input-area {
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.8) 0%, rgba(255, 255, 255, 0.9) 100%);
}
.input-row-top {
    display: flex;
    gap: 6px;
    width: 100%;
    align-items: flex-end;
}
.input-wrapper {
    flex: 1;
    position: relative;
    min-width: 0;
}
.chat-input {
    width: 100%;
    background: var(--bg-input);
    border: 1px solid var(--border);
    color: var(--text-primary);
    padding: 8px 12px;
    font-family: var(--font-sans);
    font-size: 12.5px;
    border-radius: var(--radius);
    resize: none;
    outline: none;
    transition: all var(--transition);
    line-height: 1.5;
    min-height: 36px;
    max-height: 100px;
}
.chat-input:focus {
    border-color: var(--accent-blue);
    box-shadow: 0 0 0 3px var(--shadow-glow), 0 0 20px rgba(88, 166, 255, 0.08);
}
.chat-input::placeholder {
    color: var(--text-dim);
}

.icon-btn {
    width: 34px;
    height: 34px;
    background: transparent;
    border: 1px solid var(--border);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all var(--transition);
    flex-shrink: 0;
    border-radius: var(--radius);
    color: var(--text-secondary);
    font-size: 9px;
    font-family: var(--font-display);
    font-weight: 600;
    letter-spacing: 0.5px;
    position: relative;
}
.icon-btn:hover {
    background: var(--bg-hover);
    border-color: var(--border-active);
    color: var(--text-primary);
    box-shadow: 0 0 12px var(--shadow-glow);
}
.icon-btn.recording-active {
    background: rgba(248, 81, 73, 0.1);
    border-color: var(--accent-red);
    color: var(--accent-red);
    animation: recordingPulse 0.7s ease-in-out infinite;
    box-shadow: 0 0 20px rgba(248, 81, 73, 0.15);
}
@keyframes recordingPulse {
    0%,
    100% {
        box-shadow: 0 0 8px rgba(248, 81, 73, 0.1);
    }
    50% {
        box-shadow: 0 0 24px rgba(248, 81, 73, 0.35);
    }
}

.send-btn {
    width: 36px;
    height: 36px;
    background: linear-gradient(135deg, #1f6feb 0%, #58a6ff 100%);
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all var(--transition);
    flex-shrink: 0;
    border-radius: var(--radius);
    position: relative;
}
.send-btn:hover {
    background: linear-gradient(135deg, #3b82f6 0%, #79c0ff 100%);
    box-shadow: 0 0 24px var(--shadow-glow), 0 0 50px rgba(88, 166, 255, 0.15);
    transform: scale(1.04);
}
.send-btn:active {
    transform: scale(0.93);
}
.send-btn svg {
    width: 15px;
    height: 15px;
    fill: #ffffff;
    pointer-events: none;
}
.send-btn:disabled {
    opacity: 0.35;
    pointer-events: none;
}

.file-toast {
    position: absolute;
    bottom: 102px;
    left: 16px;
    background: rgba(63, 185, 80, 0.08);
    border: 1px solid rgba(63, 185, 80, 0.28);
    padding: 5px 12px;
    border-radius: 4px;
    font-size: 8.5px;
    font-family: var(--font-display);
    color: var(--accent-mint);
    pointer-events: none;
    opacity: 0;
    transition: opacity 0.3s;
    z-index: 15;
    letter-spacing: 0.5px;
}
.file-toast.show {
    opacity: 1;
}
.file-toast.error {
    border-color: var(--accent-red);
    color: var(--accent-red);
    background: rgba(248, 81, 73, 0.07);
}

/* ════════════════════════════════════════════════════════════
   SENPAI SOCIAL CTA — floating 3D-logo orb + follow panel
   A tiny second Three.js scene (its own canvas/renderer) spins a
   DNA-colored icosahedron as the "media logo." Click it to reveal
   YouTube / GitHub / X — each link glows in its own brand color
   on hover so the CTA still reads as one of the 10 DNA-style
   color moments rather than a generic footer.
   ════════════════════════════════════════════════════════════ */
.senpai-cta {
    position: fixed;
    left: 18px;
    bottom: 18px;
    z-index: 150;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 10px;
    font-family: var(--font-sans);
}
.cta-orb {
    position: relative;
    width: 58px;
    height: 58px;
    border-radius: 50%;
    padding: 0;
    border: 1px solid var(--border-strong);
    background: radial-gradient(circle at 35% 30%, #14161b 0%, #050608 75%);
    cursor: pointer;
    overflow: hidden;
    box-shadow: 0 0 0 0 rgba(0, 212, 255, 0.35), 0 6px 24px rgba(0, 0, 0, 0.5);
    animation: ctaPulseRing 2.6s ease-out infinite;
    transition: transform 0.2s ease, border-color 0.2s ease;
}
.cta-orb:hover {
    transform: scale(1.07);
    border-color: var(--accent-blue);
}
.cta-orb canvas {
    width: 100%;
    height: 100%;
    display: block;
    pointer-events: none;
}
@keyframes ctaPulseRing {
    0%   { box-shadow: 0 0 0 0 rgba(0, 212, 255, 0.35), 0 6px 24px rgba(0, 0, 0, 0.5); }
    70%  { box-shadow: 0 0 0 14px rgba(0, 212, 255, 0), 0 6px 24px rgba(0, 0, 0, 0.5); }
    100% { box-shadow: 0 0 0 0 rgba(0, 212, 255, 0), 0 6px 24px rgba(0, 0, 0, 0.5); }
}
.cta-panel {
    position: absolute;
    left: 0;
    bottom: 70px;
    width: 190px;
    background: var(--bg-panel);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 10px;
    display: flex;
    flex-direction: column;
    gap: 6px;
    opacity: 0;
    transform: translateY(8px) scale(0.96);
    pointer-events: none;
    transition: opacity 0.18s ease, transform 0.18s ease;
    box-shadow: 0 12px 36px rgba(0, 0, 0, 0.6);
}
.cta-panel.open {
    opacity: 1;
    transform: translateY(0) scale(1);
    pointer-events: all;
}
.cta-panel-title {
    font-family: var(--font-display);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1.5px;
    color: var(--text-secondary);
    padding: 2px 6px 6px;
    border-bottom: 1px solid var(--border);
    margin-bottom: 2px;
}
.cta-panel-title span { color: var(--ink-red, var(--accent-red)); }
.cta-link {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 10px;
    border-radius: 8px;
    background: var(--bg-raised);
    border: 1px solid var(--border);
    color: var(--text-primary);
    text-decoration: none;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.3px;
    transition: all 0.15s ease;
}
.cta-link svg {
    width: 16px;
    height: 16px;
    fill: var(--text-secondary);
    flex-shrink: 0;
    transition: fill 0.15s ease;
}
.cta-link:hover { transform: translateX(2px); }
.cta-youtube:hover { border-color: #ff0000; box-shadow: 0 0 14px rgba(255, 0, 0, 0.25); }
.cta-youtube:hover svg { fill: #ff0000; }
.cta-github:hover { border-color: #e6e6e6; box-shadow: 0 0 14px rgba(255, 255, 255, 0.15); }
.cta-github:hover svg { fill: #e6e6e6; }
.cta-x:hover { border-color: #ffffff; box-shadow: 0 0 14px rgba(255, 255, 255, 0.2); }
.cta-x:hover svg { fill: #ffffff; }

@media (max-width: 640px) {
    .senpai-cta { left: 10px; bottom: 10px; }
    .cta-orb { width: 48px; height: 48px; }
}

/* Command Palette */
.command-palette {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.6);
    backdrop-filter: blur(4px);
    z-index: 200;
    display: flex;
    align-items: flex-start;
    justify-content: center;
    padding-top: 20vh;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.2s;
}
.command-palette.active {
    opacity: 1;
    pointer-events: all;
}
.command-palette .cp-box {
    background: var(--bg-panel);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    width: 90%;
    max-width: 480px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.8);
    overflow: hidden;
}
.command-palette .cp-input {
    width: 100%;
    padding: 14px 16px;
    background: var(--bg-input);
    border: none;
    border-bottom: 1px solid var(--border);
    color: var(--text-primary);
    font-size: 14px;
    font-family: var(--font-mono);
    outline: none;
}
.command-palette .cp-input:focus {
    box-shadow: 0 0 0 3px var(--shadow-glow);
}
.command-palette .cp-results {
    max-height: 200px;
    overflow-y: auto;
    padding: 6px 0;
}
.command-palette .cp-result {
    padding: 8px 16px;
    font-size: 12px;
    font-family: var(--font-sans);
    color: var(--text-secondary);
    cursor: pointer;
    transition: background 0.1s;
}
.command-palette .cp-result:hover,
.command-palette .cp-result.selected {
    background: var(--bg-hover);
    color: var(--text-primary);
}
.command-palette .cp-result .cmd-name {
    color: var(--accent-blue);
    font-weight: 600;
}

/* Settings overlay */
.settings-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.75);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    z-index: 100;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    pointer-events: none;
    transition: opacity 0.3s;
}
.settings-overlay.active {
    opacity: 1;
    pointer-events: all;
}
.settings-panel {
    background: var(--bg-panel);
    border: 1px solid var(--border);
    box-shadow: 0 0 80px rgba(0, 0, 0, 0.8), 0 0 30px var(--shadow-glow);
    padding: 22px 22px 20px;
    border-radius: var(--radius);
    width: 92%;
    max-width: 820px;
    max-height: 90vh;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    position: relative;
    transition: background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease;
}
.settings-panel h3 {
    font-family: var(--font-display);
    font-size: 14px;
    font-weight: 700;
    letter-spacing: 2.5px;
    color: var(--accent-blue);
    margin-bottom: 4px;
    text-align: center;
    text-shadow: 0 0 24px var(--shadow-glow), 0 0 50px rgba(88, 166, 255, 0.1);
    transition: color 0.3s ease, text-shadow 0.3s ease;
    flex-shrink: 0;
}
.settings-subtitle {
    text-align: center;
    font-family: var(--font-display);
    font-size: 7.5px;
    color: var(--text-dim);
    letter-spacing: 1.5px;
    margin-bottom: 16px;
    text-transform: uppercase;
    flex-shrink: 0;
}
/* Body = vertical tab rail + scrollable content pane, side by side.
   Easier to scan 9 sections than a wrapping row of top tabs. */
.settings-body {
    display: flex;
    gap: 18px;
    overflow: hidden;
    flex: 1;
    min-height: 0;
}
.settings-tabs {
    display: flex;
    flex-direction: column;
    gap: 2px;
    flex-shrink: 0;
    width: 132px;
    border-inline-end: 1px solid var(--border);
    padding-inline-end: 10px;
    overflow-y: auto;
    transition: border-color 0.3s ease;
}
.settings-tab {
    font-family: var(--font-display);
    font-size: 8px;
    font-weight: 600;
    letter-spacing: 1px;
    padding: 8px 10px;
    background: transparent;
    border: none;
    border-inline-start: 2px solid transparent;
    color: var(--text-secondary);
    cursor: pointer;
    text-transform: uppercase;
    text-align: start;
    border-radius: 4px;
    transition: all var(--transition);
}
.settings-tab:hover {
    color: var(--text-primary);
    background: var(--bg-hover);
}
.settings-tab.active {
    color: var(--accent-blue);
    border-inline-start-color: var(--accent-blue);
    background: rgba(0, 212, 255, 0.06);
}
.settings-tabpanels {
    flex: 1;
    min-width: 0;
    overflow-y: auto;
    padding-inline-end: 4px;
}
.settings-tabpanel {
    display: none;
}
.settings-tabpanel.active {
    display: block;
}
@media (max-width: 640px) {
    .settings-body { flex-direction: column; }
    .settings-tabs {
        flex-direction: row;
        flex-wrap: wrap;
        width: 100%;
        border-inline-end: none;
        border-bottom: 1px solid var(--border);
        padding-inline-end: 0;
        padding-bottom: 8px;
    }
    .settings-tab.active { border-inline-start-color: transparent; border-bottom: 2px solid var(--accent-blue); }
}

.setting-group {
    margin-bottom: 13px;
}
.setting-group label {
    display: block;
    font-family: var(--font-display);
    font-size: 7.5px;
    font-weight: 600;
    letter-spacing: 1.2px;
    color: var(--text-secondary);
    margin-bottom: 5px;
    text-transform: uppercase;
    transition: color 0.3s ease;
}
.setting-group .hint {
    font-size: 8px;
    color: var(--text-dim);
    margin-top: 4px;
    font-family: var(--font-mono);
    line-height: 1.5;
}
.setting-group input,
.setting-group select,
.setting-group textarea {
