    background-position: right 10px center;
    padding-right: 32px;
}
.setting-group select option {
    background: var(--bg-panel);
    color: var(--text-primary);
}
.input-with-btn {
    display: flex;
    gap: 6px;
}
.input-with-btn input,
.input-with-btn select {
    flex: 1;
}
.password-wrapper {
    position: relative;
}
.password-toggle {
    position: absolute;
    right: 8px;
    top: 50%;
    transform: translateY(-50%);
    background: none;
    border: none;
    color: var(--text-secondary);
    cursor: pointer;
    font-family: var(--font-display);
    font-size: 7px;
    font-weight: 600;
    letter-spacing: 0.5px;
    padding: 4px 8px;
    border-radius: 3px;
}
.password-toggle:hover {
    color: var(--text-primary);
    background: var(--bg-hover);
}
.temp-display {
    display: inline-block;
    font-family: var(--font-mono);
    font-size: 13px;
    font-weight: 600;
    color: var(--accent-blue);
    margin-left: 8px;
    min-width: 28px;
    transition: color 0.3s ease;
}
.temp-slider {
    -webkit-appearance: none;
    width: 100%;
    height: 4px;
    background: var(--border);
    border-radius: 2px;
    outline: none;
    cursor: pointer;
    transition: background 0.3s ease;
}
.temp-slider::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: var(--accent-blue);
    box-shadow: 0 0 16px var(--shadow-glow);
    cursor: pointer;
    border: 2px solid var(--bg-canvas);
    transition: background 0.3s ease, box-shadow 0.3s ease;
}
.settings-actions {
    display: flex;
    gap: 8px;
    margin-top: 18px;
    justify-content: flex-end;
    flex-shrink: 0;
}
.close-settings {
    position: absolute;
    top: 10px;
    right: 14px;
    background: none;
    border: none;
    color: var(--text-secondary);
    font-size: 18px;
    cursor: pointer;
    font-family: var(--font-sans);
    transition: color var(--transition);
}
.close-settings:hover {
    color: var(--text-primary);
}
.model-fetch-status {
    font-family: var(--font-mono);
    font-size: 8px;
    color: var(--text-dim);
    margin-top: 4px;
    display: flex;
    align-items: center;
    gap: 5px;
}
.model-fetch-status.ok {
    color: var(--accent-mint);
}
.model-fetch-status.err {
    color: var(--accent-red);
}
.model-fetch-status.loading {
    color: var(--accent-amber);
}
.custom-model-row {
    display: flex;
    gap: 6px;
    margin-top: 6px;
}
.custom-model-row input {
    flex: 1;
}
.custom-model-row button {
    font-family: var(--font-display);
    font-size: 8px;
    font-weight: 600;
    padding: 0 12px;
    white-space: nowrap;
    background: rgba(88, 166, 255, 0.1);
    border: 1px solid var(--accent-blue);
    color: var(--accent-blue);
    border-radius: var(--radius);
    cursor: pointer;
    transition: all var(--transition);
}
.custom-model-row button:hover {
    background: rgba(88, 166, 255, 0.2);
}
.token-budget-row {
    display: flex;
    gap: 8px;
}
.token-budget-row>div {
    flex: 1;
}
.checkbox-row {
    display: flex;
    align-items: center;
    gap: 8px;
}
.checkbox-row input[type="checkbox"] {
    width: auto;
    accent-color: var(--accent-blue);
    cursor: pointer;
}
.checkbox-row label {
    margin-bottom: 0;
    cursor: pointer;
}
.pricing-grid {
    display: flex;
    gap: 8px;
}
.pricing-grid>div {
    flex: 1;
}
.ollama-url-hint {
    font-size: 8px;
    color: var(--text-dim);
    margin-top: 3px;
    font-family: var(--font-mono);
}

.theme-selector {
    display: flex;
    gap: 6px;
    flex-wrap: wrap;
}
.theme-btn {
    font-family: var(--font-display);
    font-size: 7.5px;
    font-weight: 600;
    padding: 6px 12px;
    background: transparent;
    border: 1px solid var(--border);
    color: var(--text-secondary);
    cursor: pointer;
    border-radius: var(--radius);
    transition: all var(--transition);
    text-transform: uppercase;
    letter-spacing: 0.8px;
}
.theme-btn:hover {
    background: var(--bg-hover);
    border-color: var(--border-active);
    color: var(--text-primary);
}
.theme-btn.active {
    background: rgba(88, 166, 255, 0.1);
    border-color: var(--accent-blue);
    color: var(--accent-blue);
    box-shadow: 0 0 12px var(--shadow-glow);
}
.theme-btn.system-theme {
    border-color: var(--accent-amber);
    color: var(--accent-amber);
}

#refreshModelsBtn {
    display: inline-flex;
    align-items: center;
    font-family: var(--font-display);
    font-size: 8px;
    font-weight: 600;
    padding: 0 12px;
    background: rgba(88, 166, 255, 0.1);
    border: 1px solid var(--accent-blue);
    color: var(--accent-blue);
    border-radius: 6px;
    cursor: pointer;
    white-space: nowrap;
    transition: all var(--transition);
    letter-spacing: 0.5px;
}
#refreshModelsBtn:hover {
    background: rgba(88, 166, 255, 0.2);
}

.search-bar {
    padding: 6px 14px;
    border-bottom: 1px solid var(--border);
    display: none;
    gap: 6px;
    align-items: center;
    background: rgba(13, 17, 23, 0.3);
    transition: background 0.3s ease, border-color 0.3s ease;
}
[data-theme="github-light"] .search-bar {
    background: rgba(255, 255, 255, 0.3);
}
.search-bar.active {
    display: flex;
}
.search-bar input {
    flex: 1;
    background: var(--bg-input);
    border: 1px solid var(--border);
    color: var(--text-primary);
    padding: 4px 10px;
    border-radius: var(--radius);
    font-size: 11px;
    font-family: var(--font-sans);
    outline: none;
    transition: all var(--transition);
}
.search-bar input:focus {
    border-color: var(--accent-blue);
    box-shadow: 0 0 0 2px var(--shadow-glow);
}
.search-bar .search-close {
    background: none;
    border: none;
    color: var(--text-secondary);
    cursor: pointer;
    font-size: 14px;
    padding: 0 4px;
}
.search-bar .search-close:hover {
    color: var(--text-primary);
}
.search-bar .search-count {
    font-size: 8px;
    color: var(--text-dim);
    font-family: var(--font-mono);
    white-space: nowrap;
}
.search-bar .search-regex-toggle {
    font-size: 7px;
    font-family: var(--font-display);
    background: transparent;
    border: 1px solid var(--border);
    color: var(--text-secondary);
    padding: 2px 6px;
    border-radius: 4px;
    cursor: pointer;
    transition: all var(--transition);
}
.search-bar .search-regex-toggle.active {
    background: rgba(88, 166, 255, 0.1);
    border-color: var(--accent-blue);
    color: var(--accent-blue);
}

.conv-list {
    position: absolute;
    top: 0;
    right: -320px;
    width: 320px;
    height: 100%;
    background: var(--bg-panel);
    border-left: 1px solid var(--border);
    transition: right 0.3s ease;
    z-index: 25;
    padding: 14px;
    overflow-y: auto;
    box-shadow: -4px 0 30px rgba(0, 0, 0, 0.5);
}
.conv-list.open {
    right: 0;
}
.conv-list h4 {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 1.5px;
    color: var(--text-secondary);
    margin-bottom: 10px;
}
.conv-item {
    padding: 8px 10px;
    border: 1px solid var(--border);
    border-radius: var(--radius);
    margin-bottom: 6px;
    cursor: pointer;
    transition: all var(--transition);
    font-size: 11px;
    color: var(--text-primary);
}
.conv-item:hover {
    background: var(--bg-hover);
    border-color: var(--border-active);
}
.conv-item .conv-date {
    font-size: 8px;
    color: var(--text-dim);
    font-family: var(--font-mono);
}

/* Search results panel */
.search-results-panel {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: var(--bg-panel);
    border-left: 1px solid var(--border);
    z-index: 30;
    padding: 14px;
    overflow-y: auto;
    display: none;
    transition: background 0.3s ease, border-color 0.3s ease;
}
.search-results-panel.active {
    display: block;
}
.search-results-panel h4 {
    font-family: var(--font-display);
    font-size: 10px;
    letter-spacing: 1.5px;
    color: var(--text-secondary);
    margin-bottom: 10px;
}
.search-result-item {
    padding: 8px 10px;
    border: 1px solid var(--border);
    border-radius: var(--radius);
    margin-bottom: 6px;
    cursor: pointer;
    transition: all var(--transition);
    font-size: 11px;
    color: var(--text-primary);
}
.search-result-item:hover {
    background: var(--bg-hover);
    border-color: var(--border-active);
}
.search-result-item .sr-preview {
    font-size: 9px;
    color: var(--text-secondary);
    font-family: var(--font-mono);
    max-height: 40px;
    overflow: hidden;
    text-overflow: ellipsis;
}

@media (max-width: 820px) {
    .app-container {
        flex-direction: column;
    }
    .brain-section {
        flex: 0 0 30%;
        width: 100%;
        min-height: 180px;
    }
    .chat-panel {
        flex: 1 1 auto;
        width: 100%;
        border-left: none;
        border-top: 1px solid var(--border);
    }
    .corner-bracket {
        width: 18px;
        height: 18px;
    }
    .bracket-tl {
        top: 7px;
        left: 7px;
    }
    .bracket-tr {
        top: 7px;
        right: 7px;
    }
    .bracket-bl {
        bottom: 7px;
        left: 7px;
    }
    .bracket-br {
        bottom: 7px;
        right: 7px;
    }
    .status-labels {
        bottom: 7px;
        left: 7px;
    }
    .status-label {
        font-size: 6px;
    }
    .data-readouts {
        top: 7px;
        right: 7px;
    }
    .data-readout {
        font-size: 6px;
    }
    .arc-ring-1 {
        width: 130px;
        height: 130px;
    }
    .arc-ring-2 {
        width: 170px;
        height: 170px;
    }
    .arc-ring-3 {
        width: 100px;
        height: 100px;
    }
    .message {
        max-width: 95%;
        font-size: 11px;
        padding: 8px 12px;
    }
    .settings-panel {
        width: 96%;
        padding: 16px 14px;
    }
    .icon-btn {
        width: 30px;
        height: 30px;
        font-size: 8px;
    }
    .send-btn {
        width: 32px;
        height: 32px;
    }
    .chat-header-title {
        font-size: 10px;
        letter-spacing: 1.5px;
    }
    .hud-btn {
        font-size: 6.5px;
        padding: 4px 7px;
    }
    /* Keep icons, drop text labels on the mode/system buttons so the
       header stays one tidy row instead of wrapping into several. */
    .header-group .hud-btn span {
        display: none;
    }
    .header-group .hud-btn {
        padding: 6px;
        width: 26px;
        height: 26px;
        justify-content: center;
    }
    .model-switcher {
        max-width: 84px;
    }
    .chat-input {
        font-size: 11px;
        padding: 6px 10px;
        min-height: 32px;
    }
    .input-area {
        padding: 7px 10px;
    }
    .token-meter {
        padding: 6px 10px 7px;
    }
    .conv-list {
        width: 260px;
        right: -260px;
    }
    .search-results-panel {
        width: 100%;
    }
    .settings-panel {
        max-width: 100%;
        width: 100%;
        border-radius: 0;
        max-height: 100vh;
    }
}
@media (max-width: 480px) {
    .brain-section {
        flex: 0 0 24%;
        min-height: 140px;
    }
    .messages-container {
        padding: 8px 10px;
        gap: 8px;
    }
    .message {
        font-size: 10px;
        padding: 6px 10px;
    }
    .settings-panel {
        padding: 12px 10px;
    }
    .settings-panel h3 {
        font-size: 11px;
    }
    .token-budget-row,
    .pricing-grid {
        flex-direction: column;
    }
    .conv-list {
        width: 200px;
        right: -200px;
    }
}
@media (max-width: 820px) {
    .scan-line {
        display: none;
    }
}

