        try {
            const pinned = JSON.parse(localStorage.getItem('senpai_neural_v1_pinned'));
            if (pinned && Array.isArray(pinned)) appState.chat.pinnedMessages = pinned;
        } catch (_) {}
        applySettingsToUI();
